const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let attemptStarted=false;
let activeTest=1, inLibrary=false, pendingTest=null, pendingRetry=null;
const questionBase=n=>{const p=TEST.pairs.find(p=>n===p.n||n===p.n+1);return p?p.n:n};
let section=1, answers={}, submitted=false, result=null, started=Date.now(), elapsed=0, chosen='', sources={}, positions={};
const audioByTest={1:sources};
let selectedQuestion=null;
let reviewingId=null, reviewBackup=null, storageNotice='';
let accountRecords=[],accountUser=null,pendingSave=null;
const authenticatedMode=window.ECHO_AUTH===true;
async function accountAPI(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',signal:AbortSignal.timeout(15000)});if(response.status===401){location.assign('/login');throw Error('login_required')}if(!response.ok)throw Error('request_failed');return response.json();}
const HISTORY_KEY='echoprep:listening-vol9-test1:history:v1';
function getHistory(){if(authenticatedMode)return accountRecords;try{const list=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');return Array.isArray(list)?list.filter(r=>r&&typeof r.id==='string'&&r.answers&&r.result?.rows?.length===40&&Number.isFinite(r.elapsed)):[]}catch{return []}}
async function saveAttempt(){const record=pendingSave||{testId:activeTest,id:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random(),test:`Listening - Vol 9 · Test ${activeTest}`,submittedAt:new Date().toISOString(),elapsed,answers:{...answers},result:JSON.parse(JSON.stringify(result))};
 if(authenticatedMode){try{await accountAPI('/api/history',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});if(!accountRecords.some(r=>r.id===record.id))accountRecords.push(record);pendingSave=null;storageNotice='Đã lưu lượt làm vào tài khoản '+accountUser;}catch{pendingSave=record;storageNotice='Chưa lưu được lịch sử. Hãy thử lưu lại trước khi rời trang.'}return;}
 try{const history=getHistory();history.push(record);localStorage.setItem(HISTORY_KEY,JSON.stringify(history));storageNotice='Đã lưu lượt làm này vào lịch sử trên trình duyệt.'}catch{storageNotice='Trình duyệt không cho lưu lịch sử hoặc đã hết dung lượng. Kết quả hiện tại vẫn xem được trong phiên này.'}}

const duration=seconds=>[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(x=>String(x).padStart(2,'0')).join(':');
const audio=$('audio'), labels=['music room','assembly hall','computer room','cloakroom','Head’s office','gym','reception'];
const clock=()=>{if(attemptStarted&&!submitted&&!inLibrary)elapsed=Math.floor((Date.now()-started)/1000);$('timer').textContent=duration(elapsed)};setInterval(clock,1000);
function count(){const n=Object.values(answers).filter(Boolean).length;$('answered').textContent=`${n} / 40`;$('progress').style.width=`${n/40*100}%`;document.querySelectorAll('[data-jump]').forEach(b=>{b.classList.toggle('filled',!!answers[b.dataset.jump]);if(result)b.classList.add(result.rows[b.dataset.jump-1].status)});}
function options(q,multi=false){return `<div class="choice-block" id="q${q.n}"><h3><span class="qnum">${multi?q.n+'–'+(q.n+1):q.n}</span>${esc(q.prompt)}</h3>${multi?'<p class="instruction">Choose TWO correct answers.</p>':''}${q.options.map((t,i)=>{const l=String.fromCharCode(65+i);const checked=multi?[answers[q.n],answers[q.n+1]].includes(l):answers[q.n]===l;return `<label class="choice"><input type="${multi?'checkbox':'radio'}" name="q${q.n}" data-choice="${q.n}" data-multi="${multi}" value="${l}" ${checked?'checked':''} ${submitted?'disabled':''}><span class="letter">${l}</span>${esc(t)}</label>`}).join('')}</div>`}
function updateTestSelection(){document.querySelectorAll('[data-start-test]').forEach(el=>{const selected=!inLibrary&&+el.dataset.startTest===activeTest;el.classList.toggle('test-selected',selected);if(el.closest('aside')){el.style.background=selected?'#e3ecff':'#ffffff';el.style.color=selected?'#1d4ed8':'#64748b';el.style.borderColor=selected?'#8eaeff':'#dce3ed';el.style.fontWeight=selected?'700':'500';el.style.boxShadow=selected?'inset 3px 0 0 #1d4ed8':'none';}if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
function render(){
 updateTestSelection();
 const ready=!attemptStarted&&!submitted&&!inLibrary;$('start-panel').hidden=!ready;$('review-shell').hidden=ready;$('paper').hidden=ready;document.body.classList.toggle('ready-mode',ready);document.querySelector('.audio-player').hidden=ready;$('questions').hidden=ready;
 $('explanation-sheet').hidden=true;
 let body=TEST.sections[section-1].html;
 if(activeTest===1&&section===3)body='<p class="subheading">Questions 21–24</p><p class="instruction">Choose the correct answer.</p><h2>Forensic Linguistics</h2>'+TEST.singles.map(q=>options(q)).join('')+TEST.pairs.map(q=>options(q,true)).join('');
 if(activeTest===1&&section===2)body+=`<div class="map-layout"><div class="map"><img src="Listening%20-%20Vol%209/Test%201/plan.png" alt="Original Spring Down Junior School plan. Question 18 is right of the main entrance, 19 is left of the classrooms, 20 is next to the main hall.">${[18,19,20].map(n=>`<label class="map-slot slot${n}" data-drop="${n}" id="q${n}"><span>${n}</span><select data-q="${n}" aria-label="Câu ${n}" ${submitted?'disabled':''}><option value="">Chọn</option>${labels.map((t,i)=>`<option value="${String.fromCharCode(65+i)}">${String.fromCharCode(65+i)}</option>`).join('')}</select></label>`).join('')}</div><div class="bank"><p>Kéo đáp án vào ô trên sơ đồ, hoặc chọn chữ cái.</p>${labels.map((t,i)=>`<button class="token" draggable="${!submitted}" data-token="${String.fromCharCode(65+i)}" ${submitted?'disabled':''}><b>${String.fromCharCode(65+i)}</b> ${esc(t)}</button>`).join('')}</div></div>`;
 if(activeTest===2)body=body.replace(/<div data-render-choice="(\d+)"><\/div>/g,(_,n)=>options(TEST.singles.find(q=>q.n===+n)));
 $('breadcrumb').textContent=`Listening - Vol 9 / Test ${activeTest}`;document.querySelector('.test-heading h1').textContent=`Listening Test ${activeTest}`;document.querySelector('#restart-dialog h2').textContent=`Làm lại Test ${activeTest}?`;
 $('paper').innerHTML=`<div class="paper-heading"><h2>Section ${section}</h2><span>${section===3?'Chọn đáp án':section===2?'Điền từ & sơ đồ':'Điền từ'}</span></div>${body}`;
 document.querySelectorAll('[data-q]').forEach(el=>{el.value=answers[el.dataset.q]||'';el.disabled=submitted;el.id=el.id||`q${el.dataset.q}`;el.addEventListener('input',()=>{answers[el.dataset.q]=el.value;count()})});
 document.querySelectorAll('[data-choice]').forEach(el=>el.addEventListener('change',()=>{const n=+el.dataset.choice;if(el.dataset.multi==='true'){const values=[...document.querySelectorAll(`[data-choice="${n}"]:checked`)].map(x=>x.value);if(values.length>2){el.checked=false;return}answers[n]=values[0]||'';answers[n+1]=values[1]||''}else answers[n]=el.value;count()}));
 document.querySelectorAll('[data-token]').forEach(el=>{el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',el.dataset.token));el.addEventListener('click',()=>{chosen=el.dataset.token;document.querySelectorAll('[data-token]').forEach(x=>x.classList.toggle('selected',x===el))})});
 document.querySelectorAll('[data-drop]').forEach(el=>{el.addEventListener('dragover',e=>{if(!submitted)e.preventDefault()});const set=v=>{if(submitted||!/[A-I]/.test(v)||v.length!==1)return;const select=el.querySelector('select');if(![...select.options].some(o=>o.value===v))return;answers[el.dataset.drop]=v;select.value=v;count()};el.addEventListener('drop',e=>{e.preventDefault();set(e.dataTransfer.getData('text/plain'))});el.addEventListener('click',e=>{if(e.target.tagName!=='SELECT'&&chosen)set(chosen)})});
 $('questions').innerHTML=[1,2,3,4].map(n=>`<div class="question-group ${n===section?'active':''}" role="group" aria-label="Section ${n}" data-group="${n}">${Array.from({length:10},(_,i)=>{const q=(n-1)*10+i+1;return `<button data-jump="${q}" aria-label="Section ${n}, câu ${q}" aria-current="${n===section?'true':'false'}">${q}</button>`}).join('')}</div>`).join('');count();
 if(submitted){
  document.querySelectorAll('#paper [data-q]').forEach(el=>{if(el.closest('p'))el.closest('p').insertAdjacentHTML('beforeend',explanationButton(+el.dataset.q))});
  document.querySelectorAll('#paper .choice-block').forEach(el=>{const n=+el.id.slice(1);el.insertAdjacentHTML('beforeend',explanationButton(n)+(TEST.pairs.some(p=>p.n===n)?explanationButton(n+1):''))});
  if(activeTest===1&&section===2)$('paper').insertAdjacentHTML('beforeend','<div class="map-explanations">'+[18,19,20].map(explanationButton).join('')+'</div>');
 }
 renderReview();
 $('audio-title').textContent=`Audio · Section ${section}`;$('submit').disabled=submitted||!attemptStarted;$('submit').hidden=!attemptStarted&&!submitted;$('abort-attempt').hidden=submitted;
 if(result)document.querySelectorAll('[data-q]').forEach(el=>el.classList.add(result.rows[el.dataset.q-1].status));
}
function change(n){selectedQuestion=null;$('explanation-sheet').hidden=true;positions[section]=audio.currentTime;audio.pause();section=n;render();loadAudio();}
function loadAudio(){if(sources[section]){audio.src=sources[section];audio.onloadedmetadata=()=>{audio.currentTime=positions[section]||0;audio.playbackRate=+$('speed').value};$('audio-status').textContent=`Đã chọn audio cho Section ${section}.`}else {audio.removeAttribute('src');audio.load();$('audio-status').textContent=`Chưa chọn audio Section ${section}. Chọn file T${activeTest}-S${section}.mp3 từ máy.`}}
$('questions').addEventListener('click',e=>{const b=e.target.closest('[data-jump]');if(!b)return;const n=+b.dataset.jump,s=Math.ceil(n/10);if(s!==section)change(s);const id=questionBase(n);const el=$('q'+id);el?.scrollIntoView({behavior:'smooth',block:'center'});if(el?.matches('input,select'))el.focus({preventScroll:true});if(submitted)showExplanation(n)});
$('files').addEventListener('change',e=>{const files=[...e.target.files];let assigned=0;files.forEach(f=>{const match=f.name.match(/(?:T(\d+)[-_ ]?)?S([1-4])\b/i);if(match?.[1]&&+match[1]!==activeTest)return;let n=match?+match[2]:files.length===1?section:null;if(!n)return;if(sources[n])URL.revokeObjectURL(sources[n]);sources[n]=URL.createObjectURL(f);assigned++});loadAudio();if(!assigned)$('audio-status').textContent=`Chọn từng file để gán cho section hiện tại, hoặc dùng tên T${activeTest}-S1.mp3 … T${activeTest}-S4.mp3.`});
$('speed').onchange=()=>audio.playbackRate=+$('speed').value;$('back5').onclick=()=>audio.currentTime=Math.max(0,audio.currentTime-5);$('forward5').onclick=()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,audio.currentTime+5)};
audio.onerror=()=>$('audio-status').textContent='Không phát được file này. Hãy chọn lại file MP3 cho section hiện tại.';
$('submit').onclick=()=>{if(!attemptStarted||submitted)return;$('confirm-text').textContent=`Bạn đã trả lời ${Object.values(answers).filter(Boolean).length}/40 câu. Nộp bài để xem đúng, sai và đáp án.`;$('confirm').showModal()};$('cancel').onclick=()=>$('confirm').close();
function explanationButton(n){return `<button class="explanation-button" data-explain="${n}">Xem giải thích · Câu ${n}</button>`}
function renderReview(){
 document.body.classList.toggle('review-mode',submitted&&!$('paper').hidden);
 $('transcript-pane').hidden=!submitted;$('review-toolbar').hidden=!submitted;
 if(!submitted){$('explanation-sheet').hidden=true;return}
 $('transcript-title').textContent=`Transcript · Section ${section}`;
 $('transcript-body').innerHTML=TEST.transcriptSegments[section].map(segment=>`<div class="transcript-segment" id="${segment.id}">${segment.html}</div>`).join('');
 $('review-toolbar').innerHTML=`<strong>${result.correct}/40 đúng</strong><span>Sai: ${result.wrong} · Bỏ qua: ${result.blank}</span><button id="results-toggle">Bảng kết quả</button><button id="review-retry">Làm lại</button>${pendingSave?'<button id="retry-save">Lưu lại lịch sử</button>':''}${reviewBackup?'<button id="review-return">Trở về lượt hiện tại</button>':''}`;
 $('results-toggle').onclick=()=>{const show=$('results').hidden;$('results').hidden=!show;$('review-shell').hidden=show;$('results-toggle').textContent=show?'Transcript & câu hỏi':'Bảng kết quả'};
 if($('retry-save'))$('retry-save').onclick=async()=>{await saveAttempt();renderReview();renderResults();};
 $('review-retry').onclick=()=>$('restart-dialog').showModal();if($('review-return'))$('review-return').onclick=returnCurrent;
 document.querySelectorAll('#paper [data-q]').forEach(el=>{
  const n=+el.dataset.q,row=result.rows[n-1], container=el.closest('p')||el.closest('.map-slot');
  container.classList.add('review-question');container.dataset.reviewQuestion=n;if(el.previousElementSibling?.classList.contains('qnum'))el.previousElementSibling.dataset.reviewQuestion=n;
  if(el.closest('p'))el.insertAdjacentHTML('afterend',`<span class="answer-correction ${row.status}">${row.status==='correct'?'✓':' → '+esc(row.expected)}</span>`);
 });
 document.querySelectorAll('#paper .choice-block').forEach(el=>{const n=+el.id.slice(1);el.dataset.reviewQuestion=n;el.classList.add('review-question');const rows=result.rows.slice(n-1,TEST.pairs.some(p=>p.n===n)?n+1:n);el.insertAdjacentHTML('beforeend',`<div class="choice-feedback">${rows.map(r=>`<span class="answer-correction ${r.status}">Câu ${r.n}: ${esc(r.value)||'—'} → <strong>${esc(r.expected)}</strong> ${r.status==='correct'?'✓':'✕'}</span>`).join('')}</div>`);const correct=TEST.answers[n][0].split('/');el.querySelectorAll('.choice').forEach(label=>{const input=label.querySelector('input');if(correct.includes(input.value))label.classList.add('correct-option');else if(input.checked)label.classList.add('wrong-option')})});
}
function showExplanation(n){
 if(!submitted)return;
 const targetSection=Math.ceil(n/10);if(section!==targetSection)change(targetSection);
 $('results').hidden=true;$('review-shell').hidden=false;$('results-toggle').textContent='Bảng kết quả';
 selectedQuestion=n;$('explanation-title').textContent=`Câu ${n} · Giải thích đáp án`;
 const row=result.rows[n-1];const ids=TEST.questionSegments[n]||[];
 $('explanation-content').innerHTML=`<div class="explanation-answer"><p>Bạn trả lời: <strong>${esc(row.value)||'—'}</strong></p><p>Đáp án: <strong>${esc(row.expected)}</strong></p></div>`+(TEST.explanations[n]||`<p class="source-note">File gốc chưa có lời giải riêng cho câu này. Đoạn transcript chứa đáp án đã được đánh dấu bên trái.</p>${TEST.transcriptSegments[section].filter(segment=>ids.includes(segment.id)).map(segment=>segment.html).join('')}`);
 $('explanation-sheet').hidden=false;$('explanation-content').scrollTop=0;
 document.querySelectorAll('.transcript-segment').forEach(el=>el.classList.toggle('evidence-active',ids.includes(el.id)));
 document.querySelectorAll('[data-review-question]').forEach(el=>el.classList.toggle('question-active',+el.dataset.reviewQuestion===(questionBase(n))));
 const evidence=$(ids[0]);if(evidence){const pane=$('transcript-body');pane.scrollTo({top:Math.max(0,evidence.getBoundingClientRect().top-pane.getBoundingClientRect().top+pane.scrollTop-20),behavior:'auto'})}
 const question=$('q'+(questionBase(n)));if(question){const card=question.closest('[data-review-question]')||question,paper=$('paper');paper.scrollTo({top:Math.max(0,paper.scrollTop+card.getBoundingClientRect().top-paper.getBoundingClientRect().top-Math.max(18,(paper.clientHeight-card.offsetHeight)/2)),behavior:'auto'})}
}
$('explanation-close').onclick=()=>{$('explanation-sheet').hidden=true;selectedQuestion=null;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-explain]');if(b&&submitted){showExplanation(+b.dataset.explain);return}const q=e.target.closest('[data-review-question]');if(q&&submitted)showExplanation(+q.dataset.reviewQuestion)});
function showExam(){inLibrary=false;$('library').hidden=true;$('submit').hidden=false;$('abort-attempt').hidden=submitted; $('history').hidden=true;$('review-shell').hidden=false;$('paper').hidden=false;document.querySelector('.test-heading').hidden=false;document.querySelector('footer').hidden=false;$('results').hidden=!result;render();clock();loadAudio();if(result)renderResults();}
function renderResults(){
 $('results').hidden=true;$('results').innerHTML=`<div class="result-heading"><div><div class="eyebrow">${reviewingId?'XEM LẠI LƯỢT ĐÃ LÀM':'KẾT QUẢ LÀM BÀI'}</div><h2>${result.correct}<span> / 40 câu đúng</span></h2></div><p>Thời gian: ${esc(duration(elapsed))}</p></div><div class="stats"><div><strong>${result.correct}</strong>Đúng</div><div><strong>${result.wrong}</strong>Sai</div><div><strong>${result.blank}</strong>Bỏ qua</div></div>${storageNotice?`<p class="storage-notice" role="status">${esc(storageNotice)}</p>`:''}<div class="actions"><button id="review">Xem lại câu hỏi</button><button id="restart">Làm lại</button><button id="results-history">Lịch sử làm bài</button>${reviewBackup?'<button id="return-current">Trở về lượt hiện tại</button>':''}</div><div class="table-scroll"><table><thead><tr><th>Câu</th><th>Bạn trả lời</th><th>Đáp án</th><th>Kết quả</th><th>Chữa bài</th></tr></thead><tbody>${result.rows.map(r=>`<tr class="${r.status}"><td>${r.n}</td><td>${esc(r.value)||'—'}</td><td>${esc(r.expected)}</td><td>${r.status==='correct'?'Đúng':r.status==='wrong'?'Sai':'Bỏ qua'}</td><td>${explanationButton(r.n)}</td></tr>`).join('')}</tbody></table></div>`;
 $('review').onclick=()=>{$('results').hidden=true;$('review-shell').hidden=false;};$('restart').onclick=()=>$('restart-dialog').showModal();$('results-history').onclick=showHistory;if($('return-current'))$('return-current').onclick=returnCurrent;
}
function showHistory(){
 $('start-panel').hidden=true;document.body.classList.remove('ready-mode');
 $('library').hidden=true;
 document.body.classList.remove('review-mode');$('review-shell').hidden=true;$('review-toolbar').hidden=true;positions[section]=audio.currentTime;audio.pause();$('paper').hidden=true;$('results').hidden=true;document.querySelector('.test-heading').hidden=true;document.querySelector('footer').hidden=true;$('history').hidden=false;
 const records=getHistory().slice().reverse();$('history').innerHTML=`<div class="history-heading"><div><div class="eyebrow">LISTENING · VOL 9</div><h1>Lịch sử làm bài</h1></div><button id="history-back">${reviewBackup?'Trở về lượt hiện tại':'Trở về bài làm'}</button></div><p class="history-note">Mỗi lần nộp là một lượt riêng. ${authenticatedMode?'Lịch sử của tài khoản '+esc(accountUser)+', lưu trên máy chủ.':'Lịch sử lưu trên trình duyệt này; xoá dữ liệu trình duyệt sẽ xoá lịch sử.'}</p>${records.length?`<div class="table-scroll"><table class="history-table"><thead><tr><th>Bài / Lượt</th><th>Thời gian nộp</th><th>Thời gian làm</th><th>Tổng câu</th><th>Đúng</th><th>Sai</th><th>Bỏ qua</th><th>Tỉ lệ đúng</th><th>Thao tác</th></tr></thead><tbody>${records.map((r,i)=>`<tr><td><strong>${esc(r.test)}</strong><small>Lượt ${records.length-i}</small></td><td>${esc(new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'medium',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(r.submittedAt)))}</td><td>${duration(r.elapsed)}</td><td>40</td><td class="score-correct">${r.result.correct}</td><td class="score-wrong">${r.result.wrong}</td><td>${r.result.blank}</td><td>${r.result.correct/40*100}%<div class="progress"><i style="width:${r.result.correct/40*100}%"></i></div></td><td><div class="history-actions"><button data-history-view="${esc(r.id)}">Xem lại</button><button data-history-retry="${esc(r.id)}">Làm lại</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="history-empty"><h2>Chưa có lượt làm nào</h2><p>Nộp Listening Test 1 để lưu kết quả đầu tiên.</p></div>'}`;
 $('history-back').onclick=reviewBackup?returnCurrent:inLibrary?showLibrary:showExam;
 $('history').onclick=e=>{const view=e.target.closest('[data-history-view]'),retry=e.target.closest('[data-history-retry]');if(retry){const r=getHistory().find(x=>x.id===retry.dataset.historyRetry);pendingRetry=r?.testId||1;$('restart-dialog').showModal();return}if(view){const r=getHistory().find(x=>x.id===view.dataset.historyView);if(!r)return;if(!reviewBackup)reviewBackup={attemptStarted,activeTest,inLibrary,sources,positions,section,answers:{...answers},submitted,result,started,elapsed,reviewingId,storageNotice};audioByTest[activeTest]=sources;activeTest=r.testId||1;sources=audioByTest[activeTest]||{};positions={};TEST=TESTS[activeTest];answers={...r.answers};result=JSON.parse(JSON.stringify(r.result));elapsed=r.elapsed;submitted=true;attemptStarted=true;reviewingId=r.id;storageNotice='';section=1;showExam();}};
}
function returnCurrent(){if(reviewBackup){({attemptStarted,activeTest,inLibrary,sources,positions,section,answers,submitted,result,started,elapsed,reviewingId,storageNotice}=reviewBackup);reviewBackup=null;TEST=TESTS[activeTest];}if(inLibrary)showLibrary();else{showExam();loadAudio();}}
$('history-open').onclick=showHistory;
$('finish').onclick=async()=>{if(submitted||!attemptStarted)return;$('confirm').close();clock();submitted=true;positions[section]=audio.currentTime;audio.pause();result=EchoGrade.grade(answers,TEST.answers,TEST.grading);await saveAttempt();section=1;selectedQuestion=null;$('review-shell').hidden=false;$('explanation-sheet').hidden=true;render();loadAudio();renderResults();};
function clearAttempt(){audio.pause();attemptStarted=false;answers={};result=null;submitted=false;started=Date.now();elapsed=0;positions={};reviewingId=null;reviewBackup=null;storageNotice='';pendingSave=null;section=1;selectedQuestion=null;$('explanation-sheet').hidden=true;$('results').hidden=true;}
function startTest(id){clearAttempt();if(activeTest!==id){audioByTest[activeTest]=sources;sources=audioByTest[id]||{};}activeTest=id;TEST=TESTS[id];inLibrary=false;pendingRetry=null;pendingTest=null;showExam();clock();window.scrollTo({top:0});}
function showLibrary(){audio.pause();inLibrary=true;$('start-panel').hidden=true;document.body.classList.remove('ready-mode');updateTestSelection();document.body.classList.remove('review-mode');$('library').hidden=false;$('review-shell').hidden=true;$('review-toolbar').hidden=true;$('paper').hidden=true;$('results').hidden=true;$('history').hidden=true;document.querySelector('.test-heading').hidden=true;document.querySelector('footer').hidden=true;$('submit').hidden=true;$('abort-attempt').hidden=true;}
function requestLeave(testId=null){pendingTest=testId;if(attemptStarted&&!submitted&&!inLibrary){$('abort-dialog').showModal();}else if(testId)startTest(testId);else showLibrary();}
$('begin-attempt').onclick=()=>{if(attemptStarted||submitted||inLibrary)return;attemptStarted=true;started=Date.now();elapsed=0;render();clock();};
audio.addEventListener('play',()=>{if(!attemptStarted&&!submitted)audio.pause();});
$('back-library').onclick=()=>requestLeave();$('abort-attempt').onclick=()=>requestLeave();$('abort-continue').onclick=()=>{$('abort-dialog').close();pendingTest=null;};$('abort-confirm').onclick=()=>{const id=pendingTest;$('abort-dialog').close();clearAttempt();pendingTest=null;if(id)startTest(id);else showLibrary();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-start-test]');if(b){e.preventDefault();requestLeave(+b.dataset.startTest)}});
$('restart-cancel').onclick=()=>{$('restart-dialog').close();pendingRetry=null;};$('restart-confirm').onclick=()=>{$('restart-dialog').close();startTest(pendingRetry||activeTest);};
async function initialize(){if(authenticatedMode){try{const session=await accountAPI('/api/session');accountUser=session.username;accountRecords=await accountAPI('/api/history');const user=document.createElement('span');user.className='account-user';user.textContent=accountUser;$('history-open').before(user);const logout=document.createElement('button');logout.textContent='Đăng xuất';logout.onclick=async()=>{if(attemptStarted&&!submitted&&!inLibrary&&!confirm('Đăng xuất và bỏ lượt chưa nộp?'))return;audio.pause();await accountAPI('/api/logout',{method:'POST'});location.assign('/login');};$('history-open').after(logout);}catch{return}}render();clock();}
initialize();
